        org     $0000
        fcc     "g GCE 2026"
        fcb     $80
        fdb     $FD0D
        fcb     $F8,$50,$20,-$40
        fcc     "JOIN TEST"
        fcb     $80
        fcb     0

Start:  clr     Page
Main:   jsr     Wait_Recal
        lda     #$D0
        tfr     a,dp
        setdp   $D0
        jsr     Read_Btns
        lda     Vec_Btn_State
        bita    #$01
        beq     NoB0
        ldb     #0
        stb     Page
NoB0:
        bita    #$02
        beq     NoB1
        ldb     #1
        stb     Page
NoB1:
        bita    #$04
        beq     NoB2
        ldb     #2
        stb     Page
NoB2:
        bita    #$08
        beq     NoB3
        ldb     #3
        stb     Page
NoB3:
        ldb     Page
        lbeq    Page1
        decb
        lbeq    Page2
        decb
        lbeq    Page3
        lbra    Page4

